#include "../yellow_core.c"
int main(void){YellowGame g,h;yellow_init(&g);g.native_zubat_extension=true;g.native_clefairy_extension=true;g.map=YMapMtMoon1F;uint8_t kind=0,level=0;assert(yellow_wild_slot(&g,YMapMtMoon1F,9,&kind,&level));assert(kind==YK_CLEFAIRY&&level==11);assert(yellow_dex_number(YK_CLEFAIRY)==35);const YSpeciesInfo* p=y_species_info(kind);assert(p&&p->hp==70&&p->attack==45&&p->defense==48&&p->speed==35&&p->special==60&&p->exp_yield==68);assert(y_species_catch_rate(kind)==150);assert(y_exp_threshold(kind,11)==1064);assert(y_max_pp(YM_POUND)==35);uint8_t moves[4];y_build_moveset(kind,11,moves);assert(moves[0]==YM_POUND&&moves[1]==YM_GROWL&&moves[2]==YM_NONE);assert(y_move_available(kind,11,YM_POUND));assert(!y_move_available(kind,11,YM_SUPERSONIC));g.running=true;g.story=YStoryPikachuFollows;g.has_pikachu=1;g.pika_level=60;g.hp=y_calc_stats(YK_PIKACHU,60).hp;g.experience=y_exp_threshold(YK_PIKACHU,60);g.balls=90;yellow_begin_battle(&g,kind,level);g.foe_hp=1;g.foe_status=YStatusSleep7;for(unsigned i=0;i<60&&!g.caught_count;i++){yellow_input(&g,YOk);g.selected=yellow_active_move_count(&g);yellow_input(&g,YOk);}assert(g.caught_count==1&&g.caught[0].species==kind);YellowSave save;yellow_save_create(&g,&save);assert(sizeof(save)==132);assert(yellow_save_load(&h,&save));assert(h.caught[0].species==kind);g.map=YMapViridianCenter;g.screen=YScreenPC;assert(yellow_pc_deposit(&g,1));YellowPCSave pc;YellowPCBox box;assert(yellow_pc_save(&g.pc,save.checksum,&pc));assert(yellow_pc_restore(&box,save.checksum,&pc));assert(box.slots[0].species==kind);puts("CLEFAIRY_FAST_LV11_POUND_GROWL_CAPTURE_V13_PC_PASS");return 0;}
